let hintJobs=[];
function hintResource(source,kind,window){const id='hint-'+hintJobs.length;hintJobs.push({id,source,kind,window});return id;}
// Share background preparation and explicit unlocks; UI IDs are not media identities.
const hintRequests=new Map();
function requestHint(job){
 const spec={source:job.source,kind:job.kind,...(job.kind==='opening'&&job.window?{window:job.window}:{})};
 const key=JSON.stringify(spec);
 if(hintRequests.has(key))return hintRequests.get(key);
 const task=(async()=>{
   const response=await fetch('/api/hints',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(spec)});
   if(!response.ok){
    if([404,405,501].includes(response.status)){
     const error=new Error('This server is outdated and cannot prepare hints. Restart it from the AniLoop folder with python3 server.py, then reload this page.');
     error.outdated=true;throw error;
    }
    const detail=await response.json().catch(()=>null);
    throw new Error(detail?.error||'The media source could not be loaded. Retry the hint, or check its source in the media library.');
   }
   return await response.json();
 })();
 hintRequests.set(key,task);
 task.catch(()=>{if(hintRequests.get(key)===task)hintRequests.delete(key);});
 if(hintRequests.size>32)hintRequests.delete(hintRequests.keys().next().value);
 return task;
}
async function prepareHints(){
 const jobs=hintJobs,play=app.querySelector('[data-action="media-toggle"]');
 if(play&&jobs.some(j=>j.kind!=='cover'&&!document.getElementById(j.id)?.getAttribute('src')))play.disabled=true;
 await Promise.all(jobs.map(async job=>{
  const element=document.getElementById(job.id);
  if(!element||element.getAttribute('src')||element.dataset.loading)return;
  element.dataset.loading='true';
  try{
   const result=await requestHint(job);
   if(!element.isConnected)return;
   element.src=result.url;element.dataset.offset=result.offset||0;
   element.closest('.media-player')?.querySelector('.hint-processing')?.remove();
   if(element.matches('video')){prepareVideo();if(play)play.disabled=false;}
  }catch(error){
   if(!element.isConnected)return;
   const layout=element.closest('.video-hint-layout')||element.parentElement;
   element.closest('.media-player')?.querySelector('.hint-processing')?.remove();
   const windowNote=layout.querySelector('.video-window-note');
   if(windowNote)windowNote.textContent='Video hint unavailable. Full audio is still available.';
   // One full-width message for both failed resources; never squeeze errors into a cover.
   if(error.outdated){
    if(layout.querySelector('.hint-server-error'))return;
    layout.querySelectorAll('.hint-error').forEach(note=>note.remove());
    const note=document.createElement('div');note.className='media-error hint-error hint-server-error';note.setAttribute('role','alert');
    const title=document.createElement('strong');title.textContent='Restart the local server';
    const text=document.createElement('p');text.textContent=error.message;
    note.append(title,text);if(layout.matches('.video-hint-layout')){const audio=document.createElement('button');audio.className='btn secondary small';audio.dataset.action='music-mode:audio';audio.textContent='Continue with full audio';note.append(audio);}layout.prepend(note);return;
   }
   const note=document.createElement('div');note.className='media-error hint-error';note.setAttribute('role','status');
   const text=document.createElement('p');text.textContent=(job.kind==='cover'?'Cover hint: ':'Video hint: ')+error.message;
   const retry=document.createElement('button');retry.className='btn ghost small';retry.textContent='Retry hint';
   retry.addEventListener('click',()=>{layout.querySelectorAll('.hint-error').forEach(note=>note.remove());prepareHints();});
   note.append(text,retry);layout.append(note);
  }finally{delete element.dataset.loading;}
 }));
}

let currentUser=null,board={mode:'infinity',period:'all',entries:[],loading:false,error:''},boardRequest=0;
async function communityAPI(path,data){
 const response=await fetch(path,{method:data===undefined?'GET':'POST',credentials:'same-origin',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});
 const payload=await response.json().catch(()=>null);
 if(!response.ok)throw new Error(payload?.error||'Accounts need the current AniLoop server. Restart python3 server.py and use its printed URL.');
 return payload;
}
function authDialog(mode='login'){
 const register=mode==='register';
 dialog.innerHTML=`<div class="dialog-head"><div><span class="mode-label">Your place in the loop</span><h2 id="dialog-title">${register?'Create your account':'Welcome back'}</h2></div>${button('close-dialog','×','','aria-label="Close dialog"')}</div><p class="subtle">${register?'Choose a public username. Your submitted scores will appear on the community leaderboard.':'Sign in to submit scores and keep your place on the leaderboard.'}</p><form data-community-form="${mode}" class="account-form"><div class="field"><label for="account-username">Username</label><input id="account-username" name="username" autocomplete="username" minlength="3" maxlength="24" required placeholder="Your anime alias"></div><div class="field"><label for="account-password">Password</label><input id="account-password" name="password" type="password" autocomplete="${register?'new-password':'current-password'}" minlength="12" maxlength="128" required placeholder="At least 12 characters"></div>${register?'<div class="field"><label for="account-confirm">Confirm password</label><input id="account-confirm" name="confirm" type="password" autocomplete="new-password" minlength="12" maxlength="128" required></div>':''}<p class="account-error" role="alert" hidden></p><button class="btn full" type="submit">${register?'Create account':'Sign in'}</button></form><div class="account-switch">${register?'Already have an account?':'New to AniLoop?'} ${button(register?'login':'register',register?'Sign in':'Create account','text-button')}</div><p class="subtle account-note">Solo progress stays on this browser. No email is collected; password recovery is not available yet.</p>`;
 if(!dialog.open)dialog.showModal();dialog.querySelector('input')?.focus();
}
function accountView(){
 if(!currentUser)return `<section class="community-intro"><img class="community-logo" src="assets/mark.svg" alt="AniLoop original logo"><h1>A name for your score.</h1><p>Play as a guest, or create an account to submit completed rounds and join the community leaderboard.</p><div class="hero-actions">${button('register','Create account')}${button('login','Sign in','btn ghost')}</div></section>`;
 return `<section class="community-intro"><span class="profile-avatar ${social.frameClass()}">${esc(currentUser.username.slice(0,2).toUpperCase())}</span><span class="mode-label">Your account</span><h1>${esc(currentUser.username)}</h1><p>Your username and submitted scores are public. Your password is never stored in plain text. Solo games and custom media stay on this browser; room progress is shared on the server.</p><div class="hero-actions">${button('leaderboard','View leaderboards')}${button('logout','Sign out','btn ghost')}</div></section><section class="panel account-danger"><h2>Delete account</h2><p class="subtle">Permanently removes your account, sessions, and all your leaderboard entries. Your local game progress remains on this device.</p><form data-community-form="delete" class="account-form"><div class="field"><label for="delete-password">Current password</label><input id="delete-password" name="password" type="password" autocomplete="current-password" minlength="12" maxlength="128" required></div><label class="delete-confirm"><input type="checkbox" name="confirm" required> I want to permanently delete my account and scores.</label><p class="account-error" role="alert" hidden></p><button class="btn ghost" type="submit">Delete my account</button></form></section>`;
}
function scoreButton(){const submitted=currentUser&&session().submittedBy?.includes(currentUser.id);return completedCount(session())===5?button('submit-score',submitted?'Score submitted':'Submit to leaderboard','btn secondary',submitted?'disabled':''):'';}
function leaderboardView(){return `<section class="community-intro leaderboard-intro"><span class="mode-label">Community leaderboards</span><h1>Make your loop count.</h1><p>Best completed round per player. Ties use completed-round count, then earliest first result. Top 100 players are shown.</p></section><div class="leaderboard-toolbar"><div class="segmented" role="group" aria-label="Leaderboard mode">${['infinity','daily'].map(mode=>button('board-mode:'+mode,mode==='infinity'?'∞ Infinity':'Daily quiz',board.mode===mode?'selected':'','aria-pressed="'+(board.mode===mode)+'"')).join('')}</div><div class="field"><label for="board-period">Time period</label><select id="board-period"><option value="all" ${board.period==='all'?'selected':''}>All time</option><option value="week" ${board.period==='week'?'selected':''}>Past 7 days</option><option value="today" ${board.period==='today'?'selected':''}>Today (UTC)</option></select></div>${button('board-refresh','Refresh','btn ghost small')}</div><section class="leaderboard-panel" aria-label="Player rankings" aria-busy="${board.loading}">${board.loading?'<p class="empty" role="status">Loading player rankings…</p>':board.error?`<div class="media-error" role="alert">${esc(board.error)} ${button('board-refresh','Retry','btn ghost small')}</div>`:board.entries.length?`<div class="leaderboard-table-wrap"><table class="leaderboard-table"><thead><tr><th scope="col">Rank</th><th scope="col">Player</th><th scope="col">Best round</th><th scope="col">Rounds</th></tr></thead><tbody>${board.entries.map(entry=>`<tr class="${entry.userId===currentUser?.id?'your-rank':''}"><td><span class="rank-number ${entry.rank<=3?'podium':''}">${entry.rank}</span></td><td><strong>${esc(entry.username)}</strong>${entry.userId===currentUser?.id?'<span class="you-label">You</span>':''}</td><td class="ranking-score">${fmt(entry.score)}<small> / 100,000</small></td><td>${fmt(entry.rounds)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="leaderboard-empty"><span class="empty-rank">♧</span><h2>The first spot is open.</h2><p>No rounds have been submitted for this filter. Finish all five categories and submit your score.</p></div>'}</section><div class="leaderboard-join"><div><h2>${currentUser?'Your next round could be here.':'Give your score a name.'}</h2><p class="subtle">${currentUser?'Only completed rounds from the default media pool are eligible.':'Create an account to submit results. You can keep playing as a guest.'}</p></div><div class="hero-actions">${currentUser?(scoreButton()||button('home','Play a round')):button('register','Create account')}</div></div><p class="subtle leaderboard-note">Community scores: the server recalculates points from answers, but local quiz data remains inspectable. This is not a cheat-proof competitive ranking. Custom packs are excluded.</p>`;}
async function loadLeaderboard(){const request=++boardRequest;board.loading=true;board.error='';if(view==='leaderboard')render();try{const data=await communityAPI('/api/leaderboard?mode='+board.mode+'&period='+board.period);if(request===boardRequest)board.entries=data.entries;}catch(error){if(request===boardRequest)board.error=error.message;}finally{if(request===boardRequest){board.loading=false;if(view==='leaderboard')render();}}}
async function publishScore(){if(!currentUser){authDialog();return;}if(completedCount(session())!==5){toast('Complete all five categories first.');return;}if(session().submittedBy?.includes(currentUser.id))return;const round=session(),userId=currentUser.id;const result=await communityAPI('/api/scores',{round});(round.submittedBy??=[]).push(userId);persist();render();toast('Score submitted: '+fmt(result.score)+' points.');if(view==='leaderboard')loadLeaderboard();}
async function submitCommunity(form){const data=new FormData(form),mode=form.dataset.communityForm,error=form.querySelector('.account-error'),submit=form.querySelector('[type="submit"]');error.hidden=true;submit.disabled=true;
 try{if(mode==='delete'){await communityAPI('/api/account/delete',{password:data.get('password')});currentUser=null;social.clear();friends.clear();go('account');toast('Account and leaderboard entries deleted.');return;}
 if(mode==='register'&&data.get('password')!==data.get('confirm'))throw new Error('Your passwords do not match.');const result=await communityAPI('/api/'+mode,{username:data.get('username'),password:data.get('password')});currentUser=result.user;await social.refresh();dialog.close();render();if(view==='friends')await friends.load();toast(mode==='register'?'Account created. Welcome, '+currentUser.username+'.':'Welcome back, '+currentUser.username+'.');
 }catch(cause){error.textContent=cause.message;error.hidden=false;}finally{submit.disabled=false;}}
let libraryPage=1,libraryQuery='',libraryCategory='all',libraryTimer;
let starter,pack,state=readState(),view='home',selected=null,editing=null,audioContext=null,toastTimer;
const packKey=()=>pack.key||'custom';
const ids=()=>social.active?starter.anime:pack.anime;
const anime=id=>catalogIndex(ids()).byId.get(id);
const cat=id=>CATEGORIES.find(c=>c.id===id);
const session=()=>social.active?social.session:state.mode==='daily'?state.daily:state.infinity;
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),5500);}
function persist(){try{writeState(state);}catch{toast('Storage is full or blocked. Progress will be lost when you reload.');}}
function validSession(s){return s?.version===2&&s.packKey===packKey()&&CATEGORIES.every(c=>{const g=s.games?.[c.id];return g&&Array.isArray(g.questions)&&g.questions.length===c.rounds&&Array.isArray(g.scores)&&Array.isArray(g.answers)&&Array.isArray(g.hints)&&Array.isArray(g.guesses)&&Number.isInteger(g.index)&&g.index>=0&&g.index<c.rounds&&g.questions.flat().every(id=>anime(id));});}
function archive(s){if(!s||!Object.values(s.games||{}).some(g=>g.scores?.length))return;state.history??=[];const key=`${s.mode}:${s.seed}`;if(state.history.some(r=>r.key===key))return;captureRound(state,s,pack.name);state.history.unshift({...snapshotRound(s,pack.name),key});state.history=state.history.slice(0,100);}
function ensureSessions(){if(packKey()==='expanded-pool-v3'){for(const key of ['daily','infinity']){const prior=state[key];if(prior?.version===2&&prior.packKey==='real-pool-v2'&&CATEGORIES.every(c=>prior.games?.[c.id]?.questions?.flat().every(id=>anime(id)))){prior.packKey=packKey();if(key==='daily')prior.seed=`${dayKey()}:${packKey()}`;}}}state.version=1;state.history=Array.isArray(state.history)?state.history:[];state.mode=state.mode==='daily'?'daily':'infinity';if(!validSession(state.daily)||state.daily.seed!==`${dayKey()}:${packKey()}`){if(validSession(state.daily))archive(state.daily);state.daily=createSession('daily',dayKey(),`${dayKey()}:${packKey()}`,ids(),packKey());}if(state.infinity&&!validSession(state.infinity))archive(state.infinity);if(!validSession(state.infinity))state.infinity=createSession('infinity',1,uid(),ids(),packKey());persist();}
function stopAudio(){if(audioContext){audioContext.close().catch(()=>{});audioContext=null;}app.querySelectorAll('video,audio').forEach(m=>m.pause());}
function questionFrames(g,roundIndex=g.index){const a=anime(g.questions[roundIndex]);return (g.frames?.[roundIndex]?.length?g.frames[roundIndex]:a.screenshots.map((_,i)=>i)).map(i=>a.screenshots[i]);}
function questionCharacter(g,index,roundIndex=g.index){const a=anime(g.questions[roundIndex][index]),ref=g.characterRefs?.[roundIndex]?.[index],c=a.characters?.find(c=>c.id===ref);return c?{...a,character:c.name,characterAliases:c.aliases,characterImage:c.image}:a;}
function categorySummary(g){const total=g.scores.reduce((a,b)=>a+b,0);return `<div class="category-score"><span>${cat(selected).name} complete</span><strong>${fmt(total)}</strong><span>of ${fmt(cat(selected).max)} points</span>${button('share','↗','share-button','aria-label="Copy result"')}</div><div class="round-results">${g.questions.map((q,r)=>{const a=selected==='character'?null:anime(q),m=a?.[selected],level=g.levels?.[r]||'Mix';return `<article class="round-result"><div class="round-result-top"><h3>Question ${r+1} <span class="difficulty ${level.toLowerCase()}">${level}</span></h3><strong>${fmt(g.scores[r])} points</strong></div>${selected==='character'?`<div class="result-characters">${q.map((_,i)=>{const c=questionCharacter(g,i,r),answer=g.answers[r]?.entries?.[i];return `<div><img src="${esc(c.characterImage)}" alt="${esc(c.character)}">${characterFeedback(c,answer)}</div>`;}).join('')}</div>`:`<div class="result-anime">${a.cover?`<img class="result-cover" src="${esc(a.cover)}" alt="Cover">`:''}<div><h3>${titleMarkup(a)}</h3><p class="subtle">${a.year||''}${m?.song?' · '+esc(m.song):''}${m?.artist?' · '+esc(m.artist):''}</p>${selected==='screenshot'?`<div class="result-thumbs">${questionFrames(g,r).map(src=>`<img src="${esc(src)}" alt="Anime scene">`).join('')}</div>`:m?.audio?`<audio controls preload="none" src="${esc(m.audio)}" aria-label="${esc(m.song||'Music clip')}"></audio>`:''}</div></div>`}</article>`;}).join('')}</div><div class="summary-actions">${button('home','Back to overview')}${state.mode==='infinity'?nextButton('btn secondary'):''}</div>`;}
function characterFeedback(a,r){return `<div class="character-feedback"><p class="field-result ${r?.character?'correct':'incorrect'}"><span aria-label="Name ${r?.character?'correct':'incorrect'}">${r?.character?'✓':'✕'}</span><strong>${esc(a.character)}</strong></p><p class="field-result ${r?.anime?'correct':'incorrect'}"><span aria-label="Anime ${r?.anime?'correct':'incorrect'}">${r?.anime?'✓':'✕'}</span>${titleMarkup(a)}</p><span class="subtle">${fmt((r?.character?2000:0)+(r?.anime?500:0))} / 2,500 points</span></div>`;}
function maskTitle(value){return String(value||'').split(/(\s+)/).map(w=>/^\s+$/.test(w)?w:[...w].map((c,i)=>i===0?c:/[\p{L}\p{N}]/u.test(c)?'_':c).join('')).join('');}
function anidleClues(g,target){return `<section class="anidle-clue-panel" aria-label="Anidle clues"><h2>Clues</h2><div class="clue-panel-content"><div class="clue-cover"><img id="${hintResource(target.cover,'cover')}" alt="Blurred anime cover"></div><div class="clue-panel-text"><h3>Synopsis</h3><p class="synopsis-clue ${g.attempt<18?'locked':''}">${g.attempt>=18?esc(target.synopsis):`Unlocks in ${18-g.attempt} guesses`}</p><h3>Most popular character</h3><p class="popular-character-clue ${g.attempt<22?'locked':''}">${g.attempt>=22?esc(target.popularCharacter):`Unlocks in ${22-g.attempt} guesses`}</p></div></div></section>`;}
function anidleSummaryView(g,target){const data=summarizeAnidle(g.guesses,ids(),target);const range=b=>b.exact!==null?String(b.exact):b.lower!==null&&b.upper!==null?`${b.lower} – ${b.upper}`:b.lower!==null?`≥ ${b.lower}`:b.upper!==null?`≤ ${b.upper}`:'—';return `<div class="summary-wrap"><table class="comparison summary-table-anidle"><caption class="sr-only">Evidence from your previous guesses</caption><thead><tr>${['Known','Year','Studio','Source','Rating','Genres','Tags'].map(t=>`<th scope="col">${t}</th>`).join('')}</tr></thead><tbody><tr><td><strong>Summary</strong></td><td>${range(data.year)}</td><td>${data.studios.map(esc).join('<br>')||'—'}</td><td>${data.sources.map(esc).join('<br>')||'—'}</td><td>${range(data.score)}</td><td>${data.genres.map(t=>`<span class="tag match">${esc(t)}</span>`).join('')||'—'}</td><td>${data.tags.map(t=>`<span class="tag ${t.match==='primary'?'match':'partial'}">${esc(t.value)}</span>`).join('')||'—'}</td></tr></tbody></table></div>`;}
function prepareVideo(){const video=app.querySelector('.quiz-video');if(!video)return;const kind=selected,g=session().games[kind],media=anime(g.questions[g.index])[kind],locked=kind==='opening';const seek=app.querySelector('#video-seek'),volume=app.querySelector('#video-volume'),time=app.querySelector('#video-time'),play=app.querySelector('[data-action="media-toggle"]');let bounds={start:0,end:0},correcting=false;const clock=v=>`${Math.floor(v/60)}:${String(Math.floor(v%60)).padStart(2,'0')}`;const constrain=()=>{if(correcting||!video.dataset.positioned||!locked)return;const position=video.currentTime;if(position<bounds.start-.015||position>=bounds.end){correcting=true;if(position>=bounds.end)video.pause();video.currentTime=position<bounds.start?bounds.start:Math.max(bounds.start,bounds.end-.04);correcting=false;}};const update=()=>{constrain();if(Number.isFinite(video.duration)){seek.value=String(Math.max(0,Math.min(1000,(video.currentTime-bounds.start)/(bounds.end-bounds.start)*1000)));time.textContent=clock(video.currentTime+Number(video.dataset.offset||0))+' / '+clock(bounds.end+Number(video.dataset.offset||0));}play.textContent=video.paused?'▶':'Ⅱ';play.setAttribute('aria-label',video.paused?'Play video':'Pause video');};video.volume=Number(volume.value);const ready=()=>{if(!video.dataset.positioned&&Number.isFinite(video.duration)){bounds={start:0,end:video.duration};video.dataset.windowStart=bounds.start;video.dataset.windowEnd=bounds.end;video.currentTime=bounds.start;video.dataset.positioned='true';const note=app.querySelector('.video-window-note');if(note)note.textContent=`Locked video window: ${clock(Number(video.dataset.offset||0))} – ${clock(bounds.end+Number(video.dataset.offset||0))}`;update();}};video.addEventListener('loadedmetadata',ready);video.addEventListener('timeupdate',update);video.addEventListener('seeking',constrain);video.addEventListener('play',()=>{if(locked&&video.currentTime>=bounds.end-.1)video.currentTime=bounds.start;update();});video.addEventListener('pause',update);if(video.requestVideoFrameCallback){const frame=()=>{constrain();if(video.isConnected)video.requestVideoFrameCallback(frame);};video.requestVideoFrameCallback(frame);}if(video.readyState>=1)ready();}
function shell(content){const s=session(),count=completedCount(s);return `<header class="sidebar"><div class="header-inner"><a class="brand" href="#" data-action="home"><img src="assets/mark.svg" alt="">Ani<span>Loop</span></a><span class="sidebar-caption">Your anime quiz</span><nav aria-label="categories">${CATEGORIES.map(c=>{const g=s.games[c.id];return button(`play:${c.id}`,`<span class="nav-icon">${c.icon}</span><span>${c.name}<small>${g.done?fmt(g.scores.reduce((a,b)=>a+b,0))+' points':g.scores.length?g.scores.length+' / '+c.rounds+' questions':'Ready to play'}</small></span><span class="nav-check">${g.done?'✓':''}</span>`,view==='game'&&selected===c.id?'active':'');}).join('')}</nav><div class="sidebar-links">${[['home','Overview'],['library','Media pool'],['stats','Statistics'],['leaderboard','Leaderboards'],['friends','Friends'],['rooms','Party rooms'],['rewards','Daily rewards'],['help','How to play']].map(([id,label])=>button(id,label,view===id?'active':'')).join('')}</div><div class="sidebar-progress"><div><span>${social.active?(social.room.mode==='coop'?'∞ Co-op':'♧ Party'):state.mode==='infinity'?'∞ Infinity':'Daily quiz'}</span><strong>${fmt(totalScore(s))}</strong></div><div class="progress-track"><i style="width:${count*20}%"></i></div><p>${count} of 5 categories complete</p>${state.mode==='infinity'?nextButton('btn full small'):''}</div>${social.sidebar()}<div class="header-end"><button type="button" class="account-entry" data-action="account"><span class="avatar ${social.frameClass()}">${esc(currentUser?currentUser.username.slice(0,2).toUpperCase():'You')}</span><span>${esc(currentUser?.username||'Guest player')}<small>${currentUser?'Manage account':'Sign in / create account'}</small></span></button>${button('help','?','help-icon','aria-label="Open game rules"')}</div></div></header><main class="page" id="main">${content}</main><footer class="footer"><span>AniLoop · One anime is never enough.</span><span>${social.active?'Room progress saved on the server':'Solo progress saved on this device'}</span></footer>`;}
function modeToolbar(){return `<div class="toolbar"><div class="segmented" role="group" aria-label="Game mode">${button('mode-infinity','∞ Infinity',state.mode==='infinity'?'selected':'','aria-pressed="'+(state.mode==='infinity')+'"')}${button('mode-daily','Daily quiz',state.mode==='daily'?'selected':'','aria-pressed="'+(state.mode==='daily')+'"')}</div><span class="round-label">${state.mode==='infinity'?`Round <strong>${session().number}</strong> · No time limit`:`${new Date().toLocaleDateString('en-US')} · <span id="countdown"></span>`}</span></div>`;}
function nextButton(cls='btn'){if(social.active)return '';const s=session();return state.mode==='infinity'?button('next','Next Infinity round',cls,canAdvance(s)?'':'disabled title="Complete all five categories first."'):button('home','Back to overview',cls);}
function dashboard(){const s=session(),count=completedCount(s),first=CATEGORIES.find(c=>!s.games[c.id].done),infinity=state.mode==='infinity';return `${modeToolbar()}${count===5?`<div class="completion"><div><h2>Round complete!</h2><p>${fmt(totalScore(s))} of 100,000 points. ${infinity?'Ready for five new challenges?':'A new daily quiz arrives tomorrow.'}</p></div><div class="completion-buttons">${scoreButton()}${infinity?nextButton():button('share','Copy result','btn')}</div></div>`:''}<section class="hero"><div class="hero-copy"><span class="mode-label">${infinity?'Five categories. Keep going.':'Your daily anime challenge.'}</span><h1>${infinity?'One more anime.<br>One more loop.':'Your daily dose<br>of anime trivia.'}</h1><p>${infinity?'Screenshots, characters, openings, endings, and Anidle. Complete all five to unlock your next loop.':'Five categories. One daily challenge. Earn up to 100,000 points and come back tomorrow.'}</p><div class="hero-actions">${first?button(`play:${first.id}`,count?'Keep playing':'Start your loop'):button('share','Copy result')}${button('help','How it works','btn ghost')}</div></div><div class="hero-art cover-wall">${pack.anime.filter(a=>a.cover).slice(0,4).map(a=>`<img src="${esc(a.cover)}" alt="Anime-Cover">`).join('')}<span class="art-tag">${infinity?'∞ Five categories. One loop.':'✦ A new daily challenge awaits'}</span></div></section>${social.dailyPanel()}<section class="session-strip" aria-label="Round progress"><div class="strip-item"><span class="strip-icon">◈</span><div><strong>${fmt(totalScore(s))}<span class="subtle"> / 100,000</span></strong><p>Your score this round</p></div></div><div class="strip-item"><span class="strip-icon">∞</span><div><strong>${count}<span class="subtle"> / 5 categories</span></strong><div class="progress-track" role="progressbar" aria-label="Completed categories" aria-valuemin="0" aria-valuemax="5" aria-valuenow="${count}"><i style="width:${count*20}%"></i></div></div></div>${infinity?nextButton():`<span class="subtle">New quiz at midnight</span>`}</section><section><div class="section-top"><h2>Choose your next challenge</h2><p>Play in any order.</p></div><div class="category-grid">${CATEGORIES.map(c=>{const g=s.games[c.id],started=g.scores.length||g.guesses.length||g.hints.length;return `<button class="category-card" data-action="play:${c.id}"><div class="card-top"><span class="category-icon">${c.icon}</span><span class="badge ${g.done?'done':''}">${g.done?'✓ Complete':started?'In progress':c.id==='anidle'?'22 guesses':'3 questions'}</span></div><h3>${c.name}</h3><p>${c.description}</p><div class="card-bottom"><span>${g.done?fmt(g.scores.reduce((a,b)=>a+b,0)):'Up to '+fmt(c.max)} points</span><strong>${g.done?'View result':started?'Continue':'Play'} ↗</strong></div></button>`;}).join('')}</div></section>${mediaNotice()}`;}
function mediaNotice(){const counts=catalogIndex(pack.anime).counts;return `<aside class="notice"><span>◉</span><span><strong>${pack.anime.length} anime in the pool</strong> · ${counts.screenshot.reduce((a,b)=>a+b,0)} scene sets · ${counts.character.reduce((a,b)=>a+b,0)} characters · ${counts.opening.reduce((a,b)=>a+b,0)+counts.ending.reduce((a,b)=>a+b,0)} music tracks. Easy, Medium, and Hard are reshuffled every round. ${button('library','Explore the pool','')}</span></aside>`;}
function sidePanel(){return '';}
function options(type='anime'){const values=pack.anime.flatMap(a=>type==='anime'?[a.title,...a.aliases||[]]:[a.character,...a.characterAliases||[],...(a.characters||[]).flatMap(c=>[c.name,...c.aliases])]);return `<datalist id="${type}-options">${[...new Set(values.filter(Boolean))].map(x=>`<option value="${esc(x)}"></option>`).join('')}</datalist>`;}
function field(name,label,list='anime',value=''){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" value="${esc(value)}" data-suggest="${list}" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="${name}-suggestions" autocomplete="off" placeholder="${list==='character'?'Character name':'Type an anime title'}"><div class="suggestions" id="${name}-suggestions" role="listbox" hidden></div></div>`;}
function submitControls(extra=''){return `<div class="form-actions"><span class="subtle">${extra||'Choose a title from the suggestions.'}</span><div>${button('giveup','Give up','btn ghost small')} <button class="btn" type="submit">Submit answers</button></div></div>`;}
function gameView(){const c=cat(selected),g=session().games[selected],level=g.levels?.[g.index]||'Mix';return `${modeToolbar()}<div class="game-heading"><div><span class="mode-label">${c.icon} ${c.name}</span><h1>${g.done?'Your result':c.verb}</h1><p class="subtle round-meta">${c.id==='anidle'?`Guess ${g.attempt} / 22`:`Question ${g.index+1} / 3`} <span class="difficulty ${level.toLowerCase()}">${level}</span></p></div>${button('help','?','btn ghost small','aria-label="Show rules"')}</div><div class="game-layout"><section class="game-panel" aria-label="${esc(c.name)}">${g.done?categorySummary(g):`${selected==='screenshot'?screenshotView(g):selected==='character'?characterView(g):selected==='anidle'?anidleView(g):musicView(g)}${g.scores.length>g.index?resultView(g):''}`}</section></div>`;}
function screenshotView(g){const a=anime(g.questions[g.index]),submitted=g.scores.length>g.index,frames=questionFrames(g),index=g.activeFrame??0,src=frames[Math.min(index,frames.length-1)];return `<div class="frame-wrap"><img class="question-image" src="${esc(src)}" alt="Mystery anime scene"><span class="frame-caption">${index===0?'Original scene':'Scene clue '+index}</span></div><div class="hint-buttons">${button('view-frame:0','▧ Original scene',index===0?'unlocked':'')}${[1,2,3].map(n=>button(g.hints.includes(n)&&n<3?`view-frame:${n}`:`hint:${n}`,`${g.hints.includes(n)?'✓':'♧'} ${n===3?'Title clue':`Scene clue ${n}`} ${g.hints.includes(n)?'':'−2,500'}`,g.hints.includes(n)?'unlocked':'',submitted||n>1&&!g.hints.includes(n-1)?'disabled':'')).join('')}</div>${g.hints.includes(3)?`<p class="hint-text hint-title">Main title: ${esc(maskTitle(a.englishTitle||a.alternativeTitle||a.title))}<br>Japanese title: ${esc(maskTitle(a.japaneseTitle||a.title))}</p>`:''}${!submitted?`<form class="answer-form" data-form="anime"><div class="form-line">${field('answer','Which anime is this?')}<button class="btn" type="submit">Check answer</button></div><div class="form-actions"><span class="subtle">${fmt(roundScore('screenshot',{correct:true,hints:g.hints.length}))} points available</span>${button('giveup','Give up','btn ghost small')}</div></form>`:''}`;}
function characterView(g){const submitted=g.scores.length>g.index,answers=g.answers[g.index]?.entries||[];return `<form data-form="characters">${submitted?`<div class="round-score"><span>Your score</span><strong>${fmt(g.scores[g.index])}</strong></div>`:''}<div class="character-grid">${g.questions[g.index].map((id,i)=>{const a=questionCharacter(g,i),r=answers[i];return `<article class="character-item"><img src="${esc(a.characterImage)}" alt="Mystery character ${i+1}">${submitted?characterFeedback(a,r):`${field('character-'+i,'Character '+(i+1),'character')}${field('anime-'+i,'Anime')}`}</article>`;}).join('')}</div>${!submitted?`<div class="answer-form">${submitControls('2,000 for the name · 500 for the anime')}</div>`:''}</form>`;}
function mediaElement(m,videoUnlocked,mode='audio',cover=null){if(!m)return '<p class="media-error">No clip is available for this question.</p>';if(mode==='video'&&videoUnlocked&&m.video)return `<div class="video-hint-layout ${selected==='ending'?'with-cover':''}">${selected==='ending'&&cover?`<figure class="ending-cover"><img id="${hintResource(cover,'cover')}" alt="Blurred cover clue"><figcaption>Cover clue</figcaption></figure>`:''}<div class="media-player"><div class="video-viewport"><video class="quiz-video" preload="metadata" playsinline data-start="zero" id="${hintResource(m.video,selected,selected==='opening'?m.videoWindow:undefined)}" aria-label="Blurred video clue"></video></div><p class="hint-processing" role="status">Preparing video… You can keep listening to the full audio.</p><div class="video-controls">${button('media-toggle','▶','media-play','aria-label="Play video"')}<input id="video-seek" type="range" min="0" max="1000" step="1" value="0" aria-label="Video position"><span id="video-time" class="media-time">0:00</span><label class="volume-label" for="video-volume" aria-label="Video volume">♪</label><input id="video-volume" type="range" min="0" max="1" step="0.01" value="0.7" aria-label="Video volume">${button('media-fullscreen','⛶','media-fullscreen','aria-label="Fullscreen video"')}</div>${selected==='opening'?'<p class="video-window-note" role="status">Loading video window…</p>':''}</div></div>`;return `<div class="music-stage full-audio" id="music-stage"><audio controls preload="metadata" controlslist="nodownload" src="${esc(m.audio||m.video)}" aria-label="Full music track"></audio></div>`;}
function musicView(g){const a=anime(g.questions[g.index]),submitted=g.scores.length>g.index,m=a[selected],hasHint=g.hints.length>0,mode=g.musicMode||'audio';if(m?.video&&!submitted&&!hasHint&&mode==='audio')requestHint({source:m.video,kind:selected,window:m.videoWindow}).catch(()=>{});return `${mediaElement(m,hasHint,mode,a.cover)}<div class="hint-buttons music-mode-buttons">${button('music-mode:audio','♫ Audio only',mode==='audio'?'unlocked':'')}${button(hasHint?'music-mode:video':'hint:1',hasHint?'✓ Video clue unlocked':'♧ Unlock video clue −2,500',mode==='video'?'unlocked':'',submitted&&!hasHint?'disabled':'')}</div>${!submitted?`<form class="answer-form" data-form="anime"><div class="form-line">${field('answer','Which anime is this track from?')}<button class="btn" type="submit">Check answer</button></div><div class="form-actions"><span class="subtle">${fmt(roundScore(selected,{correct:true,hints:g.hints.length}))} points available · complete audio track</span>${button('giveup','Give up','btn ghost small')}</div></form>`:''}`;}
function anidleView(g){const target=anime(g.questions[0]),done=g.done;return `${g.attempt>=13?anidleClues(g,target):''}<div class="anidle-intro"><p class="subtle">${g.guesses.length?'Use the matches from your previous guesses.':'Start with any anime. Your first three guesses cost no points.'}</p>${g.attempt<13?`<p class="clue-countdown">First clue in ${13-g.attempt} guesses</p>`:''}</div>${!done?`<form class="answer-form" data-form="anidle"><div class="form-line">${field('answer',`Your guess · Attempt ${g.attempt} / 22`)}<button type="submit" class="btn">Check guess</button></div><div class="form-actions">${g.attempt>3&&clueTarget(g.attempt)?button('skip-anidle',`⏩ Skip to ${g.attempt<13?'first':g.attempt<18?'next':'last'} clue · Guess ${clueTarget(g.attempt)}`,'btn secondary small'): '<span></span>'}${button('giveup','Give up','btn ghost small')}</div></form>`:''}${g.guesses.length?`<div class="summary-toggle"><button type="button" data-action="toggle-summary" role="switch" aria-checked="${state.showSummary!==false}" aria-controls="anidle-summary">Summary <span class="switch ${state.showSummary!==false?'on':''}"></span></button></div><div id="anidle-summary" ${state.showSummary===false?'hidden':''}>${anidleSummaryView(g,target)}</div><div class="comparison-wrap"><table class="comparison"><caption class="sr-only">Compare your guesses with the target anime</caption><thead><tr>${['Anime','Year','Studio','Source','Rating','Genres','Tags'].map(t=>`<th scope="col">${t}</th>`).join('')}</tr></thead><tbody>${[...g.guesses].reverse().map(guess=>{const a=anime(guess.id),r=compareAnime(a,target);return `<tr><td><strong>${titleMarkup(a)}</strong><br><span class="subtle">Guess ${guess.attempt}</span></td><td><span class="tag ${r.year?'miss':'match'}">${a.year??'—'} ${r.year>0?'↑':r.year<0?'↓':'✓'}</span></td><td><span class="tag ${r.studio?'match':'miss'}">${esc(a.studio)}</span></td><td><span class="tag ${r.source?'match':'miss'}">${esc(a.source)}</span></td><td><span class="tag ${r.score===null?'':r.score?'miss':'match'}">${a.score??'—'} ${r.score===null?'':r.score>0?'↑':r.score<0?'↓':'✓'}</span><small class="score-source">${esc(a.scoreSource||'MyAnimeList')}</small></td><td>${r.genres.map(t=>`<span class="tag ${t.match?'match':'miss'}">${esc(t.value)}</span>`).join('')}</td><td>${r.tags.map(t=>`<span class="tag ${t.match==='primary'?'match':t.match==='secondary'?'partial':'miss'}">${esc(t.value)}</span>`).join('')}</td></tr>`;}).join('')}</tbody></table></div><p class="subtle" style="margin-top:12px">Green = match · Amber = secondary tag · Red = no match. ↑ higher / later, ↓ lower / earlier.</p>`:''}`;}
function resultView(g){const score=g.scores[g.index],a=selected==='character'?null:anime(g.questions[g.index]),answer=g.answers[g.index];return `<div class="result ${score===0?'wrong':''}" role="status"><strong>${score===0?'Question complete.':'Well spotted!'}</strong><div class="result-score">${fmt(score)} points</div>${a?`<p>The answer: <strong>${titleMarkup(a)}</strong></p>`:''}${answer?.value?`<p class="subtle">Your answer: ${esc(answer.value)}</p>`:''}${g.done?`<p style="margin-top:8px">Category complete: ${fmt(g.scores.reduce((a,b)=>a+b,0))} / ${fmt(cat(selected).max)} points.</p>${button('home','Back to categories')}`:button('continue','Next question')}</div>`;}
function statsView(){return statistics.view();}
function libraryView(){const counts=catalogIndex(pack.anime).counts,filtered=catalogIndex(pack.anime).search(libraryQuery,libraryCategory),pages=Math.max(1,Math.ceil(filtered.length/60));libraryPage=Math.min(libraryPage,pages);const visible=filtered.slice((libraryPage-1)*60,libraryPage*60);return `<div class="content-copy"><span class="mode-label">The collection behind your quiz</span><h1>Real scenes.<br>Unforgettable tracks.</h1><p>Real anime scenes, character portraits, and complete opening and ending tracks. Media loads on demand into a bounded local cache. Every round draws new questions from this collection.</p></div><div class="pool-stats">${['Easy','Medium','Hard'].map((level,i)=>`<div><span class="difficulty ${level.toLowerCase()}">${level}</span><strong>${counts.screenshot[i]} scene sets · ${counts.character[i]} characters</strong><span>${counts.opening[i]} Openings · ${counts.ending[i]} Endings</span></div>`).join('')}</div><div class="library-tools">${button('export-pack','Export pack','btn secondary')}${button('import-pack','Import pack','btn ghost')}${packKey()!==starter.key?button('restore-pack','Restore default pool','btn ghost'):''}<input type="file" id="import-file" accept="application/json,.json" hidden></div><p class="subtle" style="margin-top:18px"><strong>${esc(pack.name)}</strong> · ${pack.anime.length} anime. The library reveals answers. Source attribution is recorded in data/media-sources.json and data/media-index.json.</p><div class="pool-search"><div class="field"><label for="library-search">Search anime or characters</label><input id="library-search" type="search" value="${esc(libraryQuery)}" placeholder="Type a title or name"></div><div class="field" style="margin-top:12px"><label for="library-category">Category</label><select id="library-category"><option value="all">All anime</option>${CATEGORIES.map(c=>`<option value="${c.id}" ${libraryCategory===c.id?'selected':''}>${c.name}</option>`).join('')}</select></div></div><p class="pool-results-count" id="pool-results">${filtered.length} results · Page ${libraryPage} of ${pages} · up to 60 entries per page</p><div class="library-list">${!visible.length?`<div class="library-empty" role="status"><h3>No anime found</h3><p>Try another title or character name, or choose a different category.</p>${button('clear-library','Clear search','btn ghost small')}</div>`:''}${visible.map(a=>`<article class="library-item">${a.cover||a.characterImage||a.screenshots[0]?`<img loading="lazy" src="${esc(a.cover||a.characterImage||a.screenshots[0])}" decoding="async" alt="Cover of ${esc(a.englishTitle||a.alternativeTitle||a.title)}">`:'<span class="cover-placeholder">▧</span>'}<div class="library-item-copy"><h3>${titleMarkup(a)}</h3><p>${a.year||'Unknown year'} · ${[a.screenshots.length?'Screenshots':'',a.characters?.length?'characters':'',a.opening?'OP':'',a.ending?'ED':''].filter(Boolean).join(' / ')}</p>${button(`edit:${a.id}`,'View / edit media','')}</div></article>`).join('')}</div><div class="library-pagination">${button('library-page:'+String(libraryPage-1),'‹ Previous','btn ghost small',libraryPage<=1?'disabled':'')}<span>${libraryPage} / ${pages}</span>${button('library-page:'+String(libraryPage+1),'Next ›','btn ghost small',libraryPage>=pages?'disabled':'')}</div>${editing?editorView(anime(editing)):''}`;}
function editorView(a){return `<section class="panel editor" id="media-editor"><div class="section-top"><h2>${titleMarkup(a)}</h2>${button('close-editor','Close','btn ghost small')}</div><form data-form="editor"><div class="editor-body"><div class="field wide"><label for="screenshots">Screenshot URLs (one per line, up to three)</label><textarea name="screenshots" id="screenshots">${esc(a.screenshots.slice(0,3).filter(s=>!s.startsWith('data:')).join('\n'))}</textarea><p class="subtle">Or upload images. Empty fields keep the existing media.</p><input class="file-input" type="file" name="screenshot-files" accept="image/png,image/jpeg,image/webp,image/gif" multiple aria-label="Upload screenshots"></div><div class="field wide"><label for="characterImage">Character image URL</label><input id="characterImage" name="characterImage" type="text" value="${esc(a.characterImage?.startsWith('data:')?'':a.characterImage||'')}"><input class="file-input" type="file" name="character-file" accept="image/png,image/jpeg,image/webp,image/gif" aria-label="Upload character image"></div>${['opening','ending'].map(type=>`<div class="field"><h3 style="margin-bottom:14px">${type==='opening'?'Opening':'Ending'}</h3><label for="${type}-audio">Audio URL</label><input id="${type}-audio" name="${type}-audio" value="${esc(a[type]?.audio?.startsWith('data:')?'':a[type]?.audio||'')}"><input class="file-input" type="file" name="${type}-audio-file" accept="audio/mpeg,audio/wav,audio/ogg,audio/webm" aria-label="${type}-Upload audio"><label for="${type}-video" style="margin-top:12px">Video URL (optional)</label><input id="${type}-video" name="${type}-video" value="${esc(a[type]?.video?.startsWith('data:')?'':a[type]?.video||'')}"><input class="file-input" type="file" name="${type}-video-file" accept="video/mp4,video/webm" aria-label="${type}-Upload video"><div style="margin-top:12px">${button(`preview:${a.id}:${type}`,a[type]?'▶ Listen to clip':'No clip available','btn secondary small',a[type]?'':'disabled')}</div></div>`).join('')}<div class="wide window-editor"><h4>Opening: allowed video window</h4><div class="window-fields"><div class="field"><label for="opening-start">Start (seconds)</label><input id="opening-start" name="opening-start" type="number" min="0" step="0.1" placeholder="Automatic: 35 %" value="${a.opening?.videoWindow?.startSeconds??''}"></div><div class="field"><label for="opening-end">End (seconds)</label><input id="opening-end" name="opening-end" type="number" min="0" step="0.1" placeholder="Automatic: 65 %" value="${a.opening?.videoWindow?.endSeconds??''}"></div></div><p>Leave both fields empty for 35–65% of the video. The server removes footage outside this window from the video hint. Audio remains complete.</p></div><p class="subtle wide">Hint videos should not reveal the anime title. Use media you have permission to use. Each upload is limited to 25 MB and stays on this device. Custom hint sources must be uploaded files or registered media.</p><div class="wide"><button class="btn" type="submit">Save media & start new games</button></div></div></form></section>`;}
function render(){stopAudio();hintJobs=[];app.innerHTML=shell(view==='home'?dashboard():view==='game'?gameView():view==='library'?libraryView():view==='friends'?friends.view():social.isView(view)?social.view(view):view==='leaderboard'?leaderboardView():view==='account'?accountView():statsView());updateCountdown();prepareHints();if(view==='stats')statistics.afterRender();const heading=app.querySelector('main h1');if(heading)heading.setAttribute('tabindex','-1');}
function go(newView){view=newView;render();window.scrollTo({top:0,behavior:'instant'});app.querySelector('main h1')?.focus({preventScroll:true});}
function confirmDialog(title,body,action,label){dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2>${button('close-dialog','×','','aria-label="Close dialog"')}</div><p>${body}</p><div class="form-actions">${button('close-dialog','Cancel','btn ghost')}${button(action,label)}</div>`;dialog.showModal();}
function help(){dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">How to play AniLoop</h2>${button('close-dialog','×','','aria-label="Close dialog"')}</div><div class="help-copy"><p>In Infinity, all five categories belong to one round. Complete every category to unlock the next round. Play in any order. Giving up scores zero for the current question.</p><h3>100,000 points per round</h3><ul><li><strong>Screenshots:</strong> Three questions worth 10,000 points each. Every additional clue costs 2,500 points. Each question has three real scenes, selected randomly.</li><li><strong>Characters:</strong> Three questions with four characters each. Earn 2,000 points for each name and 500 for their anime. Partial answers count.</li><li><strong>Openings & Endings:</strong> Three questions per category, worth 5,000 points each. Hear the complete opening or ending. Unlock a blurred video clue for 2,500 points. Opening video is physically trimmed to 35–65% by default. Ending video is complete, starts at zero, allows free seeking, and includes a blurred cover.</li><li><strong>Anidle:</strong> Earn 10,000 points on guesses 1–3, then lose 500 per guess, including skips. You have 22 guesses, with 500 points available on the last. Cover clue at guess 13, synopsis at 18, most popular character at 22. The summary combines evidence from previous guesses.</li></ul><p>In Anidle, green means a match and amber a secondary tag. Arrows show whether the target year or rating is higher or lower. Ratings are saved catalog values; each guess shows its source. Missing values appear as —.</p><h3>Easy, Medium, Hard</h3><p>Each category except Anidle includes one Easy, Medium, and Hard question. Anime, characters, and scenes are randomly drawn from matching pools. Previous-round titles are avoided where possible. Anidle draws from anime with complete comparison data.</p><h3>Daily quiz & saves</h3><p>The daily quiz resets at local midnight. Play as many Infinity rounds as you like. Progress is saved in your browser and custom media in IndexedDB. No account is required. Each browser has its own save.</p></div>`;dialog.showModal();}
async function playNotes(notes){stopAudio();const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio){toast('This browser does not support practice melodies.');return;}const ctx=new Audio();audioContext=ctx;await ctx.resume();const stage=document.querySelector('#music-stage');stage?.classList.add('playing');notes.forEach((n,i)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.type=i%2?'triangle':'sine';o.frequency.value=440*2**((n-69)/12);g.gain.setValueAtTime(0,ctx.currentTime+i*.3);g.gain.linearRampToValueAtTime(.14,ctx.currentTime+i*.3+.02);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+i*.3+.28);o.connect(g);g.connect(ctx.destination);o.start(ctx.currentTime+i*.3);o.stop(ctx.currentTime+i*.3+.3);});setTimeout(()=>{if(audioContext===ctx){stage?.classList.remove('playing');ctx.close().catch(()=>{});audioContext=null;}},notes.length*300+200);}
function resolveTitle(value){return ids().find(a=>matches(value,[a.title]))||ids().find(a=>matches(value,a.aliases||[]));}
function finish(score,answer){answer={...answer,hints:[...session().games[selected].hints],attempt:session().games[selected].attempt};commitRound(session(),selected,score,answer);recordActivity(state,session());captureRound(state,session(),pack.name);persist();render();}
function giveup(){const g=session().games[selected];if(g.done||g.scores.length>g.index)return;finish(0,{value:'Gave up',entries:selected==='character'?g.questions[g.index].map(()=>({character:false,anime:false})):undefined});}
async function replacePack(newPack){createSession('infinity',1,'validate',newPack?.anime||starter.anime,newPack?.key||starter.key);await savePack(newPack);archive(state.daily);archive(state.infinity);pack=newPack||starter;state.daily=null;state.infinity=null;editing=null;ensureSessions();persist();go('library');toast('Media pack activated. New rounds are ready.');}
async function handleAction(action){
 if(statistics.action(action))return;
 if(await friends.action(action))return;
 if(await social.action(action))return;
 if(action==='login'||action==='register'){authDialog(action);return;}
 if(action==='logout'){await communityAPI('/api/logout',{});currentUser=null;social.clear();friends.clear();render();toast('Signed out.');return;}
 if(action==='leaderboard'){selected=null;view='leaderboard';await loadLeaderboard();window.scrollTo({top:0});return;}
 if(action==='board-refresh'){await loadLeaderboard();return;}
 if(action.startsWith('board-mode:')){board.mode=action.split(':')[1];await loadLeaderboard();return;}
 if(action==='submit-score'){await publishScore();return;}

 if(['home','library','stats','account'].includes(action)){selected=null;go(action);return;}
 if(action==='help'){help();return;}
 if(action.startsWith('library-page:')){libraryPage=Math.max(1,Number(action.split(':')[1]));render();app.querySelector('#pool-results')?.scrollIntoView({block:'start'});return;}
 if(action==='toggle-summary'){state.showSummary=state.showSummary===false;persist();const summary=app.querySelector('#anidle-summary');if(summary)summary.hidden=!state.showSummary;const toggle=app.querySelector('[data-action=\"toggle-summary\"]');toggle?.setAttribute('aria-checked',String(state.showSummary));toggle?.querySelector('.switch')?.classList.toggle('on',state.showSummary);return;}
 if(action.startsWith('music-mode:')){const g=session().games[selected],mode=action.split(':')[1];if(mode==='video'&&!g.hints.length)return;const answer=app.querySelector('#answer')?.value||'';g.musicMode=mode;persist();render();const field=app.querySelector('#answer');if(field)field.value=answer;return;}
 if(action==='media-toggle'){const video=app.querySelector('.quiz-video');if(video){if(video.paused)await video.play();else video.pause();}return;}
 if(action==='media-fullscreen'){await app.querySelector('.media-player')?.requestFullscreen?.();return;}
 if(action==='close-dialog'){dialog.close();stopAudio();return;}
 if(action.startsWith('mode-')){state.mode=action.slice(5);persist();go('home');return;}
 if(action.startsWith('play:')){selected=action.slice(5);if(!cat(selected))return;go('game');return;}
 if(action==='next'){if(!canAdvance(session())){toast('Complete all five categories first.');return;}archive(session());state.infinity=nextInfinity(session(),ids(),uid());persist();go('home');toast(`Infinity-Round ${session().number} is ready.`);return;}
 if(action.startsWith('view-frame:')){const g=session().games.screenshot,n=Number(action.split(':')[1]);if(n!==0&&!g.hints.includes(n))return;g.activeFrame=n;persist();render();return;}
 if(action==='continue'){session().games[selected].activeFrame=0;continueCategory(session(),selected);persist();render();return;}
 if(action.startsWith('hint:')){const g=session().games[selected],n=Number(action.split(':')[1]);if(g.done||g.scores.length>g.index||g.hints.includes(n))return;if(selected==='screenshot'&&n>1&&!g.hints.includes(n-1))return;const answer=app.querySelector('#answer')?.value||'';g.hints.push(n);if(selected==='screenshot'&&n<3)g.activeFrame=n;if(selected==='opening'||selected==='ending')g.musicMode='video';persist();render();const field=app.querySelector('#answer');if(field){field.value=answer;field.focus();}return;}
 if(action==='giveup'){giveup();return;}
 if(action==='skip-anidle'){if(skipAnidle(session())){persist();render();}return;}
 if(action==='listen'){const g=session().games[selected];await playNotes(anime(g.questions[g.index])[selected].notes);return;}
 if(action.startsWith('edit:')){editing=action.slice(5);render();document.querySelector('#media-editor')?.scrollIntoView({behavior:'smooth'});return;}
 if(action==='close-editor'){editing=null;render();return;}
 if(action.startsWith('preview:')){const [,id,type]=action.split(':'),a=anime(id),m=a[type];if(!m){toast('No clip is available for this anime.');return;}if(m.demo){await playNotes(m.notes);return;}dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${titleMarkup(a)} · ${type}</h2>${button('close-dialog','×','','aria-label="Close dialog"')}</div>${m.video?`<video controls class="music-video" src="${esc(m.video)}"></video>`:`<audio controls src="${esc(m.audio)}" style="width:100%"></audio>`}`;dialog.showModal();return;}
 if(action==='share'){const text=`AniLoop ${state.mode==='infinity'?'∞ Round '+session().number:'Daily quiz '+dayKey()}: ${fmt(totalScore(session()))}/100,000 points · ${completedCount(session())}/5 categories.`;try{await navigator.clipboard.writeText(text);toast('Result copied.');}catch{dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">Your result</h2>${button('close-dialog','×','','aria-label="Close dialog"')}</div><div class="field"><textarea aria-label="Result to copy" readonly>${esc(text)}</textarea></div>`;dialog.showModal();}return;}
 if(action==='clear-library'){libraryQuery='';libraryPage=1;render();document.querySelector('#library-search')?.focus();return;}
 if(action==='export-pack'){const blob=new Blob([JSON.stringify(pack,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='aniloop-medienpaket.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
 if(action==='import-pack'){document.querySelector('#import-file').click();return;}
 if(action==='restore-pack'){confirmDialog('Restore the default pool?','Your current games will be archived. The default pool will replace your custom pack. Export it first if you want to keep it.','confirm-restore','Restore');return;}
 if(action==='confirm-restore'){dialog.close();await replacePack(null);}
}
async function fileData(file){if(file.size>25*1024*1024)throw new Error('Each file must be 25 MB or smaller.');return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('Could not read the file.'));r.readAsDataURL(file);});}
async function saveEditor(form){const data=new FormData(form),newPack=structuredClone(pack),a=newPack.anime.find(a=>a.id===editing);const shots=String(data.get('screenshots')).split('\n').map(s=>s.trim()).filter(Boolean);if(shots.length>3)throw new Error('Use up to three screenshots.');if(shots.length)a.screenshots=shots;const uploads=data.getAll('screenshot-files').filter(f=>f.size);if(uploads.length>3)throw new Error('Upload up to three screenshots.');if(uploads.length)a.screenshots=await Promise.all(uploads.map(fileData));const character=data.get('character-file');if(character?.size){a.characterImage=await fileData(character);if(a.characters?.length)a.characters[0].image=a.characterImage;}else if(data.get('characterImage').trim())a.characterImage=data.get('characterImage').trim();for(const type of ['opening','ending']){let changed=false;const media={...a[type]};for(const kind of ['audio','video']){const file=data.get(`${type}-${kind}-file`),url=data.get(`${type}-${kind}`).trim();if(file?.size){media[kind]=await fileData(file);changed=true;}else if(url){media[kind]=url;changed=true;}}if(changed){media.demo=false;media.difficulty??=a.difficulty?.anidle||'Medium';delete media.notes;a[type]=media;}}
 const startText=data.get('opening-start')?.trim()||'',endText=data.get('opening-end')?.trim()||'';if(a.opening){if(startText||endText){const start=Number(startText),end=Number(endText);if(!startText||!endText||!Number.isFinite(start)||!Number.isFinite(end)||start<0||end<=start)throw new Error('Enter a valid start and end in seconds.');if(a.opening.videoDuration&&start>=a.opening.videoDuration)throw new Error('The time window starts after the video ends.');a.opening.videoWindow={startSeconds:start,endSeconds:end};}else a.opening.videoWindow={startFraction:.35,endFraction:.65};}newPack.key=uid();newPack.name=packKey()===starter.key?'My anime media pack':pack.name;newPack.demo=newPack.anime.some(a=>a.opening?.demo||a.ending?.demo);validatePack(newPack);createSession('infinity',1,'validate',newPack.anime,newPack.key);await savePack(newPack);archive(state.daily);archive(state.infinity);pack=newPack;state.daily=null;state.infinity=null;ensureSessions();editing=a.id;render();document.querySelector('#media-editor')?.scrollIntoView();toast('Media saved. New game rounds are ready.');}
async function submit(form){const type=form.dataset.form,data=new FormData(form);if(social.active&&['anime','characters','anidle'].includes(type)){await social.answer(form);return;}if(type==='editor'){await saveEditor(form);return;}const s=session(),g=s.games[selected];if(g.done||g.scores.length>g.index)return;if(type==='anime'){const value=String(data.get('answer')).trim(),guess=resolveTitle(value);if(!guess){toast('Choose an anime from the suggestions or give up.');return;}const target=anime(g.questions[g.index]);const correct=matches(value,[target.title,...target.aliases||[]]);finish(roundScore(selected,{correct,hints:g.hints.length}),{value:guess.title,correct});return;}if(type==='characters'){let invalid=false;const entries=g.questions[g.index].map((id,i)=>{const a=questionCharacter(g,i),cv=String(data.get(`character-${i}`)).trim(),av=String(data.get(`anime-${i}`)).trim();if(cv&&!pack.anime.some(x=>matches(cv,[x.character,...x.characterAliases||[],...(x.characters||[]).flatMap(c=>[c.name,...c.aliases])])))invalid=true;if(av&&!resolveTitle(av))invalid=true;return {character:matches(cv,[a.character,...a.characterAliases||[]]),anime:matches(av,[a.title,...a.aliases||[]]),characterValue:cv,animeValue:av};});if(invalid){toast('Choose valid suggestions or leave unknown fields empty.');return;}finish(roundScore('character',{characters:entries}),{entries});return;}if(type==='anidle'){const value=String(data.get('answer')).trim(),guess=resolveTitle(value);if(!guess){toast('Choose an anime from the suggestions.');return;}if(g.guesses.some(x=>x.id===guess.id)){toast('You have already guessed this anime.');return;}recordActivity(state,s);g.guesses.push({id:guess.id,attempt:g.attempt});if(guess.id===g.questions[0]){finish(roundScore('anidle',{correct:true,attempt:g.attempt}),{value:guess.title});return;}if(g.attempt>=22){finish(0,{value:guess.title});return;}g.attempt++;persist();render();document.querySelector('#answer')?.focus();}}
function onError(error){console.error(error);toast(error.message||'The action could not be completed. Please try again.');}
function updateCountdown(){const e=document.querySelector('#countdown');if(e){const now=new Date(),midnight=new Date(now);midnight.setHours(24,0,0,0);const t=Math.max(0,Math.floor((midnight-now)/1000));e.textContent=`Resets in ${String(Math.floor(t/3600)).padStart(2,'0')}:${String(Math.floor(t/60)%60).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;}}
function closeSuggestions(){app.querySelectorAll('[data-suggest]').forEach(input=>{input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');const list=document.getElementById(input.getAttribute('aria-controls'));if(list)list.hidden=true;});}
function showSuggestions(input){const query=input.value.trim().toLocaleLowerCase('en'),list=document.getElementById(input.getAttribute('aria-controls'));if(!list)return;closeSuggestions();if(!query)return;const results=catalogIndex(ids()).suggest(query,input.dataset.suggest);list.innerHTML=results.length?results.map((r,i)=>`<button type="button" role="option" tabindex="-1" aria-selected="false" id="${input.id}-option-${i}" data-value="${esc(r.title)}"><strong>${esc(r.title)}</strong>${r.subtitle?`<small>${esc(r.subtitle)}</small>`:''}</button>`).join(''):'<p class="suggestions-empty">No matches. Try another title or name.</p>';list.hidden=false;input.setAttribute('aria-expanded','true');}
app.addEventListener('input',event=>{if(event.target.matches('[data-suggest]'))showSuggestions(event.target);});
app.addEventListener('focusin',event=>{if(event.target.matches('[data-suggest]')&&event.target.value)showSuggestions(event.target);});
app.addEventListener('pointerdown',event=>{const option=event.target.closest('.suggestions [role="option"]');if(option){event.preventDefault();const input=option.closest('.field').querySelector('input');input.value=option.dataset.value;closeSuggestions();input.focus();}else if(!event.target.closest('.field'))closeSuggestions();});
app.addEventListener('focusout',event=>{if(event.target.matches('[data-suggest]'))setTimeout(()=>{if(!event.target.closest('.field')?.contains(document.activeElement))closeSuggestions();},0);});
app.addEventListener('keydown',event=>{const input=event.target;if(!input.matches('[data-suggest]'))return;const list=document.getElementById(input.getAttribute('aria-controls'));if(!list||list.hidden)return;const options=[...list.querySelectorAll('[role="option"]')];let index=options.findIndex(o=>o.getAttribute('aria-selected')==='true');if(event.key==='Escape'){closeSuggestions();event.preventDefault();return;}if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();if(!options.length)return;index=(index+(event.key==='ArrowDown'?1:-1)+options.length)%options.length;options.forEach((o,i)=>o.setAttribute('aria-selected',String(i===index)));input.setAttribute('aria-activedescendant',options[index].id);options[index].scrollIntoView({block:'nearest'});}if(event.key==='Enter'&&index>=0){event.preventDefault();input.value=options[index].dataset.value;closeSuggestions();}});
app.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;e.preventDefault();handleAction(b.dataset.action).catch(onError);});
dialog.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)handleAction(b.dataset.action).catch(onError);});
dialog.addEventListener('close',stopAudio);
dialog.addEventListener('submit',e=>{if(e.target.dataset.communityForm){e.preventDefault();submitCommunity(e.target);}});
app.addEventListener('submit',e=>{e.preventDefault();if(e.target.dataset.friendsForm){friends.submit(e.target).catch(onError);return;}if(e.target.dataset.socialForm){social.submit(e.target).catch(onError);return;}if(e.target.dataset.communityForm){submitCommunity(e.target);return;}const form=e.target;const btn=form.querySelector('[type="submit"]');if(btn)btn.disabled=true;submit(form).catch(onError).finally(()=>{if(btn?.isConnected)btn.disabled=false;});});
app.addEventListener('input',e=>{if(e.target.id==='library-search'){libraryQuery=e.target.value;libraryPage=1;clearTimeout(libraryTimer);const cursor=e.target.selectionStart;libraryTimer=setTimeout(()=>{render();const f=app.querySelector('#library-search');f?.focus();f?.setSelectionRange(cursor,cursor);},180);return;}const video=app.querySelector('.quiz-video');if(!video)return;if(e.target.id==='video-seek'&&Number.isFinite(video.duration))video.currentTime=Number(video.dataset.windowStart||0)+Number(e.target.value)/1000*(Number(video.dataset.windowEnd||video.duration)-Number(video.dataset.windowStart||0));if(e.target.id==='video-volume')video.volume=Number(e.target.value);});
app.addEventListener('change',async e=>{if(statistics.change(e.target))return;if(e.target.id==='friends-day'){await friends.selectDay(e.target.value);return;}if(e.target.id==='board-period'){board.period=e.target.value;await loadLeaderboard();return;}if(e.target.id==='library-category'){libraryCategory=e.target.value;libraryPage=1;render();return;}if(e.target.id==='import-file'&&e.target.files[0])try{const file=e.target.files[0];if(file.size>150*1024*1024)throw new Error('The pack is too large (150 MB maximum).');const imported=validatePack(JSON.parse(await file.text()));if(imported.demo||imported.anime.some(a=>a.opening?.demo||a.ending?.demo))throw new Error('Use a pack with real media.');createSession('infinity',1,'validate',imported.anime,imported.key);imported.key=uid();window.pendingPack=imported;confirmDialog('Activate media pack?',`“${esc(imported.name)}” contains ${imported.anime.length} anime. Activating it replaces your current pack and starts new games. Export your current pack first to keep it.`,'confirm-import','Activate');}catch(error){onError(error);}});
dialog.addEventListener('click',async e=>{if(e.target.closest('[data-action="confirm-import"]')&&window.pendingPack){dialog.close();const imported=window.pendingPack;delete window.pendingPack;try{await replacePack(imported);}catch(error){onError(error);}}});
app.addEventListener('error',e=>{if(e.target.matches('img')){if(e.target.dataset.failed)return;e.target.dataset.failed='1';e.target.alt='Image unavailable. Check its source in the media library.';e.target.style.minHeight='100px';}else if(e.target.matches('audio,video')){const m=e.target;if(m.dataset.failed)return;m.dataset.failed='1';const note=document.createElement('p');note.className='media-error';note.textContent='This clip is unavailable or unsupported. Check its library source or try again.';const retry=document.createElement('button');retry.className='btn ghost small';retry.textContent='Retry';retry.addEventListener('click',()=>{m.dataset.failed='';note.remove();m.load();});note.append(' ',retry);m.after(note);}},true);
async function init(){try{const response=await fetch('data/pool.json');if(!response.ok)throw new Error('Could not load the anime pool.');starter=validatePack(await response.json());let custom;try{custom=await loadPack();if(custom)validatePack(custom);}catch{toast('Custom media could not be loaded. Using the default pool.');}pack=custom&&!custom.demo?custom:starter;ensureSessions();render();try{currentUser=(await communityAPI('/api/account')).user;}catch{currentUser=null;}await social.refresh();if(view==='friends')await friends.load();else if(view==='home')render();social.boot();setInterval(()=>{updateCountdown();social.tick();if(state.daily.seed!==`${dayKey()}:${packKey()}`){ensureSessions();if(state.mode==='daily'&&!social.active){go('home');toast('A new daily quiz has begun.');}}},1000);}catch(error){app.innerHTML=`<main class="page"><div class="panel"><h1>AniLoop could not start.</h1><p style="margin-top:20px">${esc(error.message)} Start the project with <code>python3 server.py</code> and open <a href="http://localhost:8097">localhost:8097</a>.</p></div></main>`;}}
const statistics=createStatistics({esc,fmt,button,app,state:()=>state,session:()=>session(),render,play:mode=>{state.mode=mode;persist();go('home');}});
const friends=createFriends({esc,button,fmt,api:communityAPI,user:()=>currentUser,getView:()=>view,go,render,toast,login:()=>authDialog(),playDaily:()=>{state.mode='daily';persist();go('home');}});
const social=createSocial({titleMarkup,app,dialog,esc,button,fmt,api:communityAPI,user:()=>currentUser,getView:()=>view,select:value=>{selected=value;},go,render,toast,login:()=>authDialog(),soloDaily:()=>state.daily,playDaily:()=>{state.mode='daily';persist();go('home');},anime,views:{screenshot:screenshotView,character:characterView,opening:musicView,ending:musicView,anidle:anidleView}});
init();
